const profiles={
 dad:{name:"爸爸",emoji:"👨🏻",desc:"72岁 · 长辈健康膳食",weight:"68.0",goal:"控盐关注",tags:["清淡饮食","均衡营养"],updates:[{date:"11月7日",title:"新增饮食需求",body:"医生建议减少添加糖摄入。用户已确认。"}]},
 me:{name:"我",emoji:"🙋🏻",desc:"24岁 · 体重管理",weight:"58.5",goal:"健康减脂",tags:["高蛋白","规律饮食"],updates:[{date:"11月6日",title:"更新体重",body:"记录体重 58.5 kg。"}]},
 pet:{name:"团子",emoji:"🐶",desc:"4岁 · 犬类档案",weight:"12.0",goal:"体重维护",tags:["犬类专属档案","记录主粮"],updates:[{date:"11月5日",title:"更新体重",body:"记录体重 12.0 kg。"}]}
};
const recipes=[
{id:"pet1",name:"犬类完整营养主粮选择",emoji:"🐕",image:"data:image/jpeg;base64,",desc:"按生命阶段、体重和活动水平查看完整营养主粮选择要点；不是自制配方。",tags:["pet"],time:"营养知识",nutrition:"需核对产品营养适足性声明",type:"pet"},
{id:"pet2",name:"猫类完整营养主粮选择",emoji:"🐈",desc:"猫是专性肉食动物，查看生命阶段和完整营养声明；不使用人类减盐/减脂食谱。",tags:["pet"],time:"营养知识",nutrition:"需核对产品营养适足性声明",type:"pet"},
{id:"r1",name:"西兰花鸡胸肉杂粮饭",emoji:"🥦",image:"data:image/jpeg;base64,",desc:"鸡胸肉、西兰花、杂粮；适合做份量管理。",tags:["high_protein","low_salt"],time:"约25分钟",nutrition:"营养值待按实际克数核算",type:"human"},
{id:"r2",name:"清蒸鱼配时蔬",emoji:"🐟",image:"data:image/jpeg;base64,",desc:"鱼类、时令蔬菜；少盐调味思路。",tags:["low_salt","high_protein"],time:"约20分钟",nutrition:"营养值待按实际克数核算",type:"human"},
{id:"r3",name:"菌菇豆腐汤",emoji:"🍲",image:"data:image/jpeg;base64,",desc:"菌菇、豆腐和青菜；简单清淡的家常汤品。",tags:["low_salt","low_sugar"],time:"约18分钟",nutrition:"营养值待按实际克数核算",type:"human"},
{id:"r4",name:"燕麦鸡蛋早餐",emoji:"🥣",image:"data:image/jpeg;base64,",desc:"燕麦、鸡蛋、无添加糖牛奶选项。",tags:["low_sugar","high_protein"],time:"约12分钟",nutrition:"营养值待按实际克数核算",type:"human"},
{id:"r5",name:"南瓜小米粥",emoji:"🎃",image:"data:image/jpeg;base64,",desc:"软质主食候选；需按个人营养需求搭配蛋白质。",tags:["low_salt"],time:"约30分钟",nutrition:"营养值待按实际克数核算",type:"human"},
{id:"r6",name:"鸡肉菌菇蒸蛋",emoji:"🍄",image:"data:image/jpeg;base64,",desc:"鸡蛋、鸡肉、菌菇；可调整质地。",tags:["high_protein","low_sugar"],time:"约22分钟",nutrition:"营养值待按实际克数核算",type:"human"}
];
let state=JSON.parse(localStorage.getItem("sm_demo")||"null")||{profile:"dad",tasks:[],meals:[
{meal:"早餐",name:"燕麦牛奶 + 水煮蛋",time:"08:00",status:"已食用",feedback:"份量合适",rating:4,emoji:"🥚"},
{meal:"午餐",name:"清蒸鱼 + 西兰花 + 杂粮饭",time:"12:10",status:"已食用",feedback:"喜欢清淡口味",rating:5,emoji:"🐟"},
{meal:"晚餐",name:"菌菇豆腐汤",time:"18:30",status:"计划食用",feedback:"",rating:0,emoji:"🍲"}
],updates:[{date:"11月7日",title:"医生建议",body:"减少添加糖摄入（演示记录，需用户确认）。"}]};
function save(){state.tasks=state.tasks||[];localStorage.setItem("sm_demo",JSON.stringify(state));render()}
function toast(s){let t=document.getElementById("toast");t.textContent=s;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2200)}
function go(page){document.querySelectorAll(".page").forEach(x=>x.classList.toggle("active",x.id===page));document.querySelectorAll("[data-page]").forEach(x=>x.classList.toggle("active",x.dataset.page===page));window.scrollTo(0,0)}
document.querySelectorAll("[data-page]").forEach(b=>b.addEventListener("click",()=>go(b.dataset.page)));
document.getElementById("profileSelect").addEventListener("change",e=>{state.profile=e.target.value;save()});
function render(){
let p=profiles[state.profile];document.getElementById("profileSelect").value=state.profile;
document.getElementById("profileEmoji").textContent=p.emoji;document.getElementById("profileName").textContent=p.name;document.getElementById("profileDesc").textContent=p.desc;document.getElementById("weight").textContent=p.weight;document.getElementById("goal").textContent=p.goal;
document.getElementById("tags").innerHTML=p.tags.map(t=>`<span class="tag">${t}</span>`).join("");
document.getElementById("mealCount").textContent=state.meals.filter(m=>m.status==="已食用").length;
let updateHtml=(state.updates||[]).slice().reverse().map(u=>`<div class="event"><h4>${esc(u.date)} · ${esc(u.title)}</h4><p>${esc(u.body)}</p></div>`).join("")||'<div class="empty">还没有健康变化记录</div>';
document.getElementById("recentHealth").innerHTML=updateHtml;document.getElementById("healthTimeline").innerHTML=updateHtml;
document.getElementById("goalTags").innerHTML=p.tags.map(t=>`<span class="tag">${t}</span>`).join("");
let meals=state.meals.map((m,i)=>mealHTML(m,i)).join("")||'<div class="empty">还没有饮食记录</div>';
document.getElementById("homeMeals").innerHTML=meals;document.getElementById("diaryMeals").innerHTML=meals;
document.getElementById("memoryText").textContent=`${p.name}的档案目标是「${p.goal}」。已记录${state.meals.filter(m=>m.status==="已食用").length}餐；推荐将参考实际食用记录和用户反馈。`;
let goalText=(p.goal.includes("糖")||state.updates.some(u=>u.body.includes("糖")))?"减少添加糖：优先选择无额外添加糖的食谱，不把主食碳水一概排除。":p.goal.includes("盐")?"清淡少盐：优先选择少盐烹饪和天然食材。":"结合档案偏好，推荐多样化食材和适量份量。";
document.getElementById("recommendTitle").textContent=state.profile==="me"?"西兰花鸡胸肉杂粮饭":state.profile==="pet"?"宠物档案与营养记录":"清蒸鱼 + 西兰花 + 杂粮饭";
document.getElementById("recommendReason").textContent=goalText;
let recommendRecipe=state.profile==="me"?recipes.find(r=>r.id==="r1"):recipes.find(r=>r.id==="r2");let recommendPhoto=document.getElementById("recommendPhoto");if(recommendPhoto&&recommendRecipe&&recommendRecipe.image)recommendPhoto.src=recommendRecipe.image;
renderRecipes();
let tasks=state.tasks||[];document.getElementById("taskSummary").innerHTML=tasks.length?tasks.slice(-3).reverse().map(t=>`<div class="task-step"><span class="task-dot ${t.status==="待执行"?"pending":""}"></span><strong>${esc(t.name)}</strong><span class="muted">· ${esc(t.status)}</span></div>`).join(""):"确认食谱后，任务会自动出现在这里。";
}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function mealHTML(m,i){let matched=recipes.find(r=>m.name.includes("清蒸鱼")&&r.id==="r2"||m.name.includes("西兰花鸡胸肉")&&r.id==="r1"||m.name.includes("菌菇豆腐")&&r.id==="r3"||m.name.includes("燕麦")&&r.id==="r4"||m.name.includes("南瓜小米粥")&&r.id==="r5"||m.name.includes("鸡肉菌菇蒸蛋")&&r.id==="r6");let mealImage=(matched&&matched.image)||m.image;let photo=mealImage?`<img class="meal-photo" src="${esc(mealImage)}" alt="${esc(m.name)}" data-hide-on-error>`:`<div class="meal-icon">${m.emoji||"🍽️"}</div>`;let action=m.status==="待制作"?`<button class="btn ghost" data-action="robotComplete" data-value="${i}">模拟制作完成</button>`:m.status==="已制作"?`<button class="btn ghost" data-action="markEaten" data-value="${i}">确认已食用</button>`:`<button class="btn ghost" data-action="feedback" data-value="${i}">反馈 / 修改</button>`;return `<div class="meal">${photo}<div><h4>${esc(m.meal)} · ${esc(m.name)}</h4><p>${esc(m.time||"")}　${esc(m.feedback||"暂无反馈")}</p>${m.taskId?`<p class="muted">任务 ${esc(m.taskId)} · ${esc(m.taskStatus||"已创建")}</p>`:""}</div><div><span class="status ${["计划食用","待制作","已制作"].includes(m.status)?"pending":""}">${esc(m.status)}</span><br>${action}</div></div>`}
function openMeal(){document.getElementById("modalTitle").textContent="添加一餐";document.getElementById("modalBody").innerHTML=`<div class="form-grid"><div class="field"><label>餐次</label><select id="mtype"><option>早餐</option><option>午餐</option><option>晚餐</option><option>加餐</option></select></div><div class="field"><label>时间</label><input id="mtime" type="time" value="18:00"></div><div class="field full"><label>吃了什么</label><input id="mname" placeholder="例如：清蒸鱼、西兰花、杂粮饭"></div><div class="field"><label>状态</label><select id="mstatus"><option>已食用</option><option>已制作</option><option>计划食用</option><option>未食用</option></select></div><div class="field"><label>评分</label><select id="mrating"><option value="5">5分</option><option value="4">4分</option><option value="3">3分</option><option value="2">2分</option><option value="1">1分</option></select></div><div class="field full"><label>反馈</label><textarea id="mfeedback" placeholder="口味、份量、饱腹感、下次想怎么调整"></textarea></div></div><button class="btn modal-action" data-action="addMeal">保存记录</button>`;document.getElementById("modal").classList.add("open")}
function addMeal(){let name=document.getElementById("mname").value.trim();if(!name){toast("请先填写餐食名称");return}state.meals.push({meal:document.getElementById("mtype").value,time:document.getElementById("mtime").value,name,status:document.getElementById("mstatus").value,rating:+document.getElementById("mrating").value,feedback:document.getElementById("mfeedback").value,emoji:"🍽️"});closeModal();save();toast("饮食记录已保存")}
function feedback(i){let m=state.meals[i];document.getElementById("modalTitle").textContent="餐食反馈";document.getElementById("modalBody").innerHTML=`<p><strong>${esc(m.name)}</strong></p><div class="form-grid"><div class="field"><label>实际状态</label><select id="fstatus">${["已食用","已制作","计划食用","未食用"].map(x=>`<option ${m.status===x?"selected":""}>${x}</option>`).join("")}</select></div><div class="field"><label>评分</label><select id="frating">${[5,4,3,2,1].map(x=>`<option value="${x}" ${m.rating===x?"selected":""}>${x}分</option>`).join("")}</select></div><div class="field full"><label>你的反馈</label><textarea id="ffb">${esc(m.feedback||"")}</textarea></div></div><button class="btn modal-action" data-action="saveFeedback" data-value="${i}">保存反馈</button>`;document.getElementById("modal").classList.add("open")}
function saveFeedback(i){state.meals[i].status=document.getElementById("fstatus").value;state.meals[i].rating=+document.getElementById("frating").value;state.meals[i].feedback=document.getElementById("ffb").value;closeModal();save();toast("反馈已保存，后续推荐会参考")}
function openHealth(){document.getElementById("modalTitle").textContent="新增健康变化";document.getElementById("modalBody").innerHTML=`<div class="form-grid"><div class="field"><label>记录日期</label><input id="hdate" type="date" value="2026-11-07"></div><div class="field"><label>记录类型</label><select id="htype"><option>医院检查</option><option>医生建议</option><option>体重变化</option><option>饮食目标调整</option></select></div><div class="field full"><label>检查项目 / 医生建议 / 新需求</label><textarea id="hbody" placeholder="例如：医生建议减少添加糖摄入；请填写医生原话或检查报告中的信息"></textarea></div><div class="field full"><label>用户确认的饮食目标</label><select id="hgoal"><option>保持原有目标</option><option>减少添加糖</option><option>清淡少盐</option><option>增加优质蛋白</option><option>均衡营养</option><option>需要专业人员进一步确认</option></select></div></div><div class="notice notice-spaced">提示：系统只记录用户提供的检查信息和医生建议，不自动诊断疾病或改变药物治疗。</div><button class="btn modal-action" data-action="addHealth">确认并保存</button>`;document.getElementById("modal").classList.add("open")}
function addHealth(){let body=document.getElementById("hbody").value.trim();if(!body){toast("请填写检查信息或医生建议");return}let goal=document.getElementById("hgoal").value;state.updates.push({date:document.getElementById("hdate").value,title:document.getElementById("htype").value,body:body+"；目标："+goal});let p=profiles[state.profile];if(goal!=="保持原有目标"&&goal!=="需要专业人员进一步确认"){p.goal=goal;p.tags=[goal,...p.tags.filter(x=>x!==goal)]}closeModal();save();toast("健康记录已保存，推荐条件已更新")}
function openProfile(){let p=profiles[state.profile];document.getElementById("modalTitle").textContent="编辑档案";document.getElementById("modalBody").innerHTML=`<div class="form-grid"><div class="field"><label>显示名称</label><input id="pname" value="${esc(p.name)}"></div><div class="field"><label>当前体重（kg）</label><input id="pweight" type="number" step=".1" value="${p.weight}"></div><div class="field full"><label>当前饮食目标</label><select id="pgoal">${["控盐关注","减少添加糖","均衡营养","健康减脂","增加优质蛋白","体重维护"].map(x=>`<option ${p.goal===x?"selected":""}>${x}</option>`).join("")}</select></div></div><button class="btn modal-action" data-action="saveProfile">保存档案</button>`;document.getElementById("modal").classList.add("open")}
function saveProfile(){let p=profiles[state.profile];p.name=document.getElementById("pname").value;p.weight=document.getElementById("pweight").value;p.goal=document.getElementById("pgoal").value;closeModal();save();toast("档案已更新")}
function renderRecipes(){let filter=document.getElementById("recipeFilter").value;let arr=recipes.filter(r=>state.profile==="pet"?r.type==="pet":r.type==="human"&&(filter==="all"||r.tags.includes(filter)));document.getElementById("recipeList").innerHTML=(state.profile==="pet"?`<div class="notice grid-full">宠物档案仅展示犬猫营养知识与主粮选择提示。此演示不生成自制主食配方；长期自制饮食应由兽医营养专业人员制定。</div>`:"")+arr.map(r=>`<article class="recipe"><div class="food">${r.image?`<img src="${esc(r.image)}" alt="${esc(r.name)}">`:r.emoji}</div><div class="recipe-body"><h4>${esc(r.name)}</h4><p>${esc(r.desc)}</p><p>${esc(r.time)} · ${esc(r.nutrition)}</p><div class="recipe-actions"><button data-action="recipeDetail" data-value="${r.id}">查看详情</button><button class="primary" data-action="confirmRecipe" data-value="${r.id}">确认并制作</button></div></div></article>`).join("")+`<div class="photo-note grid-full">菜品图片为本地原型演示素材；正式上线请替换为团队自有或已获授权的菜品摄影图。</div>`}
document.getElementById("recipeFilter").addEventListener("change",renderRecipes);
function recipeDetail(id){let r=recipes.find(x=>x.id===id);document.getElementById("modalTitle").textContent=r.name;document.getElementById("modalBody").innerHTML=`${r.image?`<img src="${esc(r.image)}" alt="${esc(r.name)}"> class="detail-photo"`:`<div> class="detail-emoji"${r.emoji}</div>`}<p>${esc(r.desc)}</p><p><strong>预计时间：</strong>${esc(r.time)}</p><p><strong>营养信息：</strong>${esc(r.nutrition)}</p><div class="notice">营养值需按实际食材重量核算；机器人是否可执行需以当前GALBOT G1工具能力为准。</div><button class="btn modal-action" data-action="confirmRecipe" data-value="${r.id}">确认这道菜并创建制作任务</button>`;document.getElementById("modal").classList.add("open")}
function confirmRecipe(id){let r=recipes.find(x=>x.id===id);if(!r||r.type==="pet"){toast("宠物营养知识卡不能转换为人类备餐任务");return}document.getElementById("modalTitle").textContent="确认餐食并创建任务";document.getElementById("modalBody").innerHTML=`<div class="row align-start">${r.image?`<img src="${esc(r.image)}"> class="confirm-photo"`:""}<div><strong>${esc(r.name)}</strong><p class="muted small">${esc(r.desc)}</p></div></div><div class="field field-spaced"><label>安排到哪一餐？</label><select id="confirmMeal"><option>早餐</option><option selected>午餐</option><option>晚餐</option><option>加餐</option></select></div><div class="notice notice-spaced">点击确认后，系统会自动加入今日饮食记录，并创建一个机器人制作任务。此Demo只模拟发送，尚未连接真实G1。</div><button class="btn modal-action" data-action="confirmAndCreate" data-value="${r.id}">确认并发送制作任务</button>`;document.getElementById("modal").classList.add("open")}
function confirmAndCreate(id){let r=recipes.find(x=>x.id===id);let slot=document.getElementById("confirmMeal").value;let taskId="SM-"+Date.now().toString().slice(-6);state.tasks=state.tasks||[];state.tasks.push({id:taskId,recipeId:id,name:r.name,status:"待执行",createdAt:new Date().toLocaleString()});state.meals.push({meal:slot,name:r.name,time:new Date().toLocaleTimeString("zh-CN",{hour:"2-digit",minute:"2-digit"}),status:"待制作",feedback:"已确认菜谱，等待机器人执行",rating:0,emoji:r.emoji,image:r.image,taskId,taskStatus:"已创建"});closeModal();save();go("diary");toast("已自动记录到今日饮食，并创建机器人任务 "+taskId)}
function robotComplete(i){let m=state.meals[i];m.status="已制作";m.taskStatus="制作完成（Demo模拟）";let t=(state.tasks||[]).find(x=>x.id===m.taskId);if(t)t.status="已制作";save();toast("已模拟机器人制作完成；请确认是否实际食用")}
function markEaten(i){let m=state.meals[i];m.status="已食用";m.feedback=m.feedback||"用户确认已食用";save();toast("已记录为实际食用")}
function closeModal(){document.getElementById("modal").classList.remove("open")}

const actions = new Map(Object.entries({
  addHealth, addMeal, closeModal, confirmAndCreate, confirmRecipe, feedback, go,
  markEaten, openHealth, openMeal, openProfile, recipeDetail, robotComplete,
  saveFeedback, saveProfile,
}));

document.addEventListener("click", (event) => {
  const button = event.target.closest("button[data-action]");
  if (button) {
    actions.get(button.dataset.action)?.(button.dataset.value);
  }
});

document.addEventListener("error", (event) => {
  if (event.target instanceof HTMLImageElement && event.target.hasAttribute("data-hide-on-error")) {
    event.target.style.display = "none";
  }
}, true);

render();
